CREATE OR REPLACE FUNCTION public.check_owned_relations() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb:=to_jsonb(NEW); field text; target text; target_id uuid; valid boolean; BEGIN
FOREACH field IN ARRAY ARRAY['client_id','equipment_id','budget_id','work_order_id','product_id','service_id'] LOOP
IF r ? field AND r->>field IS NOT NULL THEN target_id:=(r->>field)::uuid; target:=CASE field WHEN 'client_id' THEN 'clients' WHEN 'equipment_id' THEN 'equipment' WHEN 'budget_id' THEN 'budgets' WHEN 'work_order_id' THEN 'work_orders' WHEN 'product_id' THEN 'products' ELSE 'services' END; EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I WHERE id=$1 AND owner_id=$2)',target) INTO valid USING target_id,NEW.owner_id; IF NOT valid THEN RAISE EXCEPTION 'Registro vinculado não pertence à sua conta'; END IF; END IF;
END LOOP; RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['equipment','budgets','budget_items','work_orders','work_order_items','technical_reports','warranties','appointments','payments','documents','inventory_movements'] LOOP EXECUTE format('CREATE TRIGGER validate_owned_relations BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.check_owned_relations()',t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.adjust_inventory(product uuid,quantity numeric,kind text,reason text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ BEGIN
IF quantity<=0 OR kind NOT IN ('entrada','saida') THEN RAISE EXCEPTION 'Quantidade ou tipo inválido'; END IF;
UPDATE public.products SET stock=stock+CASE WHEN kind='entrada' THEN quantity ELSE -quantity END WHERE id=product AND owner_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Peça não encontrada ou acesso bloqueado'; END IF;
INSERT INTO public.inventory_movements(product_id,quantity,kind,reason,owner_id) VALUES(product,quantity,kind,reason,auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.adjust_inventory(uuid,numeric,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.adjust_inventory(uuid,numeric,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.reconcile_order_stock() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old_qty numeric:=0; new_qty numeric:=0; BEGIN
IF TG_OP<>'INSERT' AND OLD.product_id IS NOT NULL THEN UPDATE public.products SET stock=stock+OLD.quantity WHERE id=OLD.product_id AND owner_id=OLD.owner_id; INSERT INTO public.inventory_movements(product_id,quantity,kind,reason,owner_id) SELECT OLD.product_id,OLD.quantity,'entrada','Ajuste de item da OS',OLD.owner_id WHERE EXISTS(SELECT 1 FROM public.products WHERE id=OLD.product_id); END IF;
IF TG_OP<>'DELETE' AND NEW.product_id IS NOT NULL THEN UPDATE public.products SET stock=stock-NEW.quantity WHERE id=NEW.product_id AND owner_id=NEW.owner_id; INSERT INTO public.inventory_movements(product_id,quantity,kind,reason,work_order_id,owner_id) VALUES(NEW.product_id,NEW.quantity,'saida','Uso em OS',NEW.work_order_id,NEW.owner_id); END IF;
IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
DROP TRIGGER trg_wo_items_stock ON public.work_order_items;
CREATE TRIGGER trg_wo_items_stock AFTER INSERT OR UPDATE OR DELETE ON public.work_order_items FOR EACH ROW EXECUTE FUNCTION public.reconcile_order_stock();
CREATE OR REPLACE FUNCTION public.save_work_order(order_id uuid,payload jsonb,items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE r public.work_orders; saved uuid; it jsonb; row_id uuid; BEGIN
IF jsonb_typeof(items)<>'array' THEN RAISE EXCEPTION 'Itens inválidos'; END IF;
IF order_id IS NOT NULL THEN SELECT * INTO r FROM public.work_orders WHERE id=order_id AND owner_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Ordem não encontrada ou acesso bloqueado'; END IF; ELSE r.id:=gen_random_uuid(); r.owner_id:=auth.uid(); END IF;
r:=jsonb_populate_record(r,payload-'id'-'owner_id'-'number'-'created_at');
IF r.client_id IS NULL OR r.service_date IS NULL OR r.total<0 THEN RAISE EXCEPTION 'Cliente, data ou valor inválido'; END IF;
IF order_id IS NULL THEN INSERT INTO public.work_orders(id,client_id,equipment_id,budget_id,service_date,service_time,service_type,technician_name,reported_problem,diagnosis,executed_service,refrigerant,refrigerant_amount,pressures,compressor_current,temperatures,tests,notes,status,photos_before,photos_during,photos_after,total,signature,signed_at,owner_id) VALUES(r.id,r.client_id,r.equipment_id,r.budget_id,r.service_date,r.service_time,r.service_type,r.technician_name,r.reported_problem,r.diagnosis,r.executed_service,r.refrigerant,r.refrigerant_amount,r.pressures,r.compressor_current,r.temperatures,r.tests,r.notes,coalesce(r.status,'aberta'),coalesce(r.photos_before,'{}'),coalesce(r.photos_during,'{}'),coalesce(r.photos_after,'{}'),r.total,r.signature,r.signed_at,auth.uid()) RETURNING id INTO saved;
ELSE UPDATE public.work_orders SET client_id=r.client_id,equipment_id=r.equipment_id,service_date=r.service_date,service_time=r.service_time,service_type=r.service_type,technician_name=r.technician_name,reported_problem=r.reported_problem,diagnosis=r.diagnosis,executed_service=r.executed_service,refrigerant=r.refrigerant,refrigerant_amount=r.refrigerant_amount,pressures=r.pressures,compressor_current=r.compressor_current,temperatures=r.temperatures,tests=r.tests,notes=r.notes,status=r.status,photos_before=r.photos_before,photos_during=r.photos_during,photos_after=r.photos_after,total=r.total,signature=r.signature,signed_at=r.signed_at WHERE id=order_id RETURNING id INTO saved; END IF;
DELETE FROM public.work_order_items WHERE work_order_id=saved AND id NOT IN (SELECT (x->>'id')::uuid FROM jsonb_array_elements(items) x WHERE nullif(x->>'id','') IS NOT NULL);
FOR it IN SELECT * FROM jsonb_array_elements(items) LOOP IF coalesce(trim(it->>'description'),'')='' OR (it->>'quantity')::numeric<=0 OR (it->>'unit_price')::numeric<0 THEN RAISE EXCEPTION 'Descrição, quantidade ou preço do item inválido'; END IF;
row_id:=nullif(it->>'id','')::uuid;
IF row_id IS NOT NULL THEN UPDATE public.work_order_items SET description=it->>'description',quantity=(it->>'quantity')::numeric,unit_price=(it->>'unit_price')::numeric,total=(it->>'quantity')::numeric*(it->>'unit_price')::numeric,product_id=nullif(it->>'product_id','')::uuid,kind=coalesce(it->>'kind','servico') WHERE id=row_id AND work_order_id=saved; IF NOT FOUND THEN RAISE EXCEPTION 'Item não pertence à ordem'; END IF;
ELSE INSERT INTO public.work_order_items(work_order_id,description,quantity,unit_price,total,product_id,kind,owner_id) VALUES(saved,it->>'description',(it->>'quantity')::numeric,(it->>'unit_price')::numeric,(it->>'quantity')::numeric*(it->>'unit_price')::numeric,nullif(it->>'product_id','')::uuid,coalesce(it->>'kind','servico'),auth.uid()); END IF; END LOOP; RETURN saved; END $$;
REVOKE ALL ON FUNCTION public.save_work_order(uuid,jsonb,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.save_work_order(uuid,jsonb,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.save_budget(payload jsonb,items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE r public.budgets; saved uuid; it jsonb; BEGIN
r:=jsonb_populate_record(NULL::public.budgets,payload-'id'-'owner_id'-'number');
IF r.client_id IS NULL OR r.issue_date IS NULL OR r.total<0 OR jsonb_array_length(items)=0 THEN RAISE EXCEPTION 'Informe cliente, data e itens válidos'; END IF;
INSERT INTO public.budgets(client_id,equipment_id,issue_date,valid_until,problem_description,discount,travel_fee,labor_total,items_total,total,payment_conditions,deadline,notes,status,owner_id) VALUES(r.client_id,r.equipment_id,r.issue_date,r.valid_until,r.problem_description,r.discount,r.travel_fee,r.labor_total,r.items_total,r.total,r.payment_conditions,r.deadline,r.notes,'rascunho',auth.uid()) RETURNING id INTO saved;
FOR it IN SELECT * FROM jsonb_array_elements(items) LOOP IF coalesce(trim(it->>'description'),'')='' OR (it->>'quantity')::numeric<=0 OR (it->>'unit_price')::numeric<0 THEN RAISE EXCEPTION 'Descrição, quantidade ou preço do item inválido'; END IF;
INSERT INTO public.budget_items(budget_id,kind,description,quantity,unit_price,total,product_id,service_id,owner_id) VALUES(saved,it->>'kind',it->>'description',(it->>'quantity')::numeric,(it->>'unit_price')::numeric,(it->>'quantity')::numeric*(it->>'unit_price')::numeric,nullif(it->>'product_id','')::uuid,nullif(it->>'service_id','')::uuid,auth.uid()); END LOOP; RETURN saved; END $$;
REVOKE ALL ON FUNCTION public.save_budget(jsonb,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.save_budget(jsonb,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.convert_budget(budget uuid) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE b public.budgets; saved uuid; BEGIN SELECT * INTO b FROM public.budgets WHERE id=budget AND owner_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Orçamento não encontrado'; END IF;
SELECT id INTO saved FROM public.work_orders WHERE budget_id=budget AND owner_id=auth.uid() LIMIT 1; IF saved IS NOT NULL THEN RETURN saved; END IF;
INSERT INTO public.work_orders(client_id,equipment_id,budget_id,service_date,reported_problem,status,total,owner_id) VALUES(b.client_id,b.equipment_id,b.id,CURRENT_DATE,b.problem_description,'aberta',b.total,auth.uid()) RETURNING id INTO saved;
INSERT INTO public.work_order_items(work_order_id,kind,description,quantity,unit_price,total,product_id,owner_id) SELECT saved,kind,description,quantity,unit_price,total,product_id,auth.uid() FROM public.budget_items WHERE budget_id=b.id; RETURN saved; END $$;
REVOKE ALL ON FUNCTION public.convert_budget(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.convert_budget(uuid) TO authenticated;
CREATE INDEX appointments_owner_schedule ON public.appointments(owner_id,scheduled_at);
CREATE INDEX guests_owner_schedule ON public.guest_appointments(owner_id,scheduled_at);
CREATE INDEX payments_owner_due ON public.payments(owner_id,status,due_date);
CREATE INDEX orders_owner_date ON public.work_orders(owner_id,service_date);
CREATE INDEX logs_owner_date ON public.activity_logs(owner_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.sync_work_order_appointment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_at timestamptz; BEGIN
IF NEW.status<>'agendada' THEN UPDATE public.appointments SET status=CASE WHEN NEW.status='cancelada' THEN 'cancelado' WHEN NEW.status='concluida' THEN 'realizado' ELSE status END WHERE work_order_id=NEW.id AND owner_id=NEW.owner_id; RETURN NEW; END IF;
v_at:=((NEW.service_date::text||' '||coalesce(nullif(NEW.service_time,''),'09:00'))::timestamp AT TIME ZONE 'America/Sao_Paulo');
IF EXISTS(SELECT 1 FROM public.appointments WHERE work_order_id=NEW.id) THEN UPDATE public.appointments SET client_id=NEW.client_id,equipment_id=NEW.equipment_id,title=concat_ws(' • ',NEW.number,nullif(NEW.service_type,'')),technician_name=NEW.technician_name,scheduled_at=v_at,reported_problem=NEW.reported_problem,status=CASE WHEN status IN ('cancelado','realizado') THEN 'agendado' ELSE status END WHERE work_order_id=NEW.id AND owner_id=NEW.owner_id;
ELSE INSERT INTO public.appointments(client_id,equipment_id,work_order_id,title,technician_name,scheduled_at,reported_problem,status,duration_minutes,owner_id) VALUES(NEW.client_id,NEW.equipment_id,NEW.id,concat_ws(' • ',NEW.number,nullif(NEW.service_type,'')),NEW.technician_name,v_at,NEW.reported_problem,'agendado',60,NEW.owner_id); END IF; RETURN NEW; END $$;